CREATE TABLE billing_policies(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL CHECK(length(digest)=64),version TEXT NOT NULL,policy_json TEXT NOT NULL CHECK(octet_length(policy_json)<=65536),actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,created_at_ms BIGINT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,digest),UNIQUE(organization_id,tenant_id,project_id,agent_uid,version),UNIQUE(organization_id,tenant_id,project_id,agent_uid,actor_id,operation_id));
CREATE TABLE billing_current(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,digest) REFERENCES billing_policies(organization_id,tenant_id,project_id,agent_uid,digest) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE billing_accounts(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,budget_key TEXT NOT NULL,window_start_ms BIGINT NOT NULL,window_end_ms BIGINT NOT NULL,currency TEXT NOT NULL,hard_micros BIGINT NOT NULL CHECK(hard_micros>=0),soft_micros BIGINT NOT NULL CHECK(soft_micros>=0 AND soft_micros<=hard_micros),reserved_micros BIGINT NOT NULL CHECK(reserved_micros>=0),consumed_micros BIGINT NOT NULL CHECK(consumed_micros>=0),revision BIGINT NOT NULL CHECK(revision>=0),PRIMARY KEY(organization_id,tenant_id,budget_key,window_start_ms));
CREATE TABLE billing_run_reservations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,run_id TEXT NOT NULL,budget_key TEXT NOT NULL,window_start_ms BIGINT NOT NULL,reserved_micros BIGINT NOT NULL CHECK(reserved_micros>=0),policy_digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('reserved','settled')),charged_micros BIGINT CHECK(charged_micros>=0),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,run_id,budget_key),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,run_id) REFERENCES runs(organization_id,tenant_id,project_id,agent_uid,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE billing_run_limits(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,run_id TEXT NOT NULL,provider_attempts BIGINT NOT NULL CHECK(provider_attempts>=0),input_upper_bound BIGINT NOT NULL CHECK(input_upper_bound>=0),sandbox_allocated_ms BIGINT NOT NULL CHECK(sandbox_allocated_ms>=0),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,run_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,run_id) REFERENCES runs(organization_id,tenant_id,project_id,agent_uid,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE billing_sandbox_allocations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,run_id TEXT NOT NULL,operation_id TEXT NOT NULL,wall_limit_ms BIGINT NOT NULL CHECK(wall_limit_ms>0),started_at_ms BIGINT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,run_id,operation_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,run_id) REFERENCES runs(organization_id,tenant_id,project_id,agent_uid,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE usage_charges(seq BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,run_id TEXT NOT NULL,operation_id TEXT NOT NULL,model TEXT,kind TEXT NOT NULL,owner_json TEXT NOT NULL CHECK(octet_length(owner_json)<=4096),units_json TEXT NOT NULL CHECK(octet_length(units_json)<=16384),policy_digest TEXT,currency TEXT,cost_micros BIGINT CHECK(cost_micros>=0),outcome_unknown BOOLEAN NOT NULL,created_at_ms BIGINT NOT NULL,UNIQUE(organization_id,tenant_id,project_id,agent_uid,operation_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,run_id) REFERENCES runs(organization_id,tenant_id,project_id,agent_uid,id) DEFERRABLE INITIALLY DEFERRED);
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['billing_sandbox_allocations','billing_run_limits','billing_policies','billing_current','billing_run_reservations','usage_charges'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_scope ON %I USING(organization_id=current_setting(''agent.organization_id'',true) AND tenant_id=current_setting(''agent.tenant_id'',true) AND project_id=current_setting(''agent.project_id'',true) AND agent_uid=current_setting(''agent.agent_uid'',true)) WITH CHECK(organization_id=current_setting(''agent.organization_id'',true) AND tenant_id=current_setting(''agent.tenant_id'',true) AND project_id=current_setting(''agent.project_id'',true) AND agent_uid=current_setting(''agent.agent_uid'',true))',t); END LOOP; END $$;
ALTER TABLE billing_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE billing_accounts FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON billing_accounts USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true));
CREATE TRIGGER immutable_billing_policy BEFORE UPDATE OR DELETE ON billing_policies FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TRIGGER immutable_usage BEFORE UPDATE OR DELETE ON usage_charges FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
